import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes2')
from h import *
X=[]
X.append(r(9584605,"Pan de ajo en freidora de aire","¡Crujiente, con ajo, mantecoso y delicioso! El pan de ajo en freidora de aire es adictivo y fácil de preparar, más crujiente que nunca y el aperitivo perfecto para cualquier comida. Listo en solo 10 minutos.","4 porciones","1 porción",
["4 rebanadas de pan ciabatta o pan francés *mis rebanadas pesaban aprox. 1.5 onzas cada una","2 cucharadas de mantequilla vegana o margarina, suavizada","4 dientes de ajo picados finamente","¼-1/2 cucharadita de perejil seco; el fresco es mejor, pero el seco también funciona","sal + pimienta al gusto"],
["Corte por la mitad la barra de ciabatta y luego corte cuatro rebanadas. (Usé aproximadamente la mitad de una barra de ciabatta por tanda.) Así que si desea usar la barra entera, tendrá unas 8 rebanadas.)","En un tazón pequeño, combine la mantequilla, el ajo y el perejil con un poco de sal y pimienta y mezcle bien. Divida la mezcla entre las cuatro rebanadas de pan y extienda de manera uniforme.","Agregue 1/4 de taza de agua a la freidora de aire, debajo de la canasta, para evitar que salga humo. Luego coloque el pan de ajo en la canasta; no hay problema si las rebanadas se superponen un poco. Ajuste la freidora a 360 grados F y cocine de 5 a 8 minutos, hasta alcanzar la textura crujiente deseada. Empiece a revisarlo alrededor de los 4 minutos."],
["Use pan de buena calidad para obtener los mejores resultados. Haga su mejor esfuerzo por cortar el pan en rebanadas del mismo tamaño para que se cocinen de manera uniforme y queden igual de crujientes. Si va a preparar varias tandas, tenga en cuenta que las tandas siguientes se cocinarán más rápido, ya que la freidora estará caliente desde el inicio. Para una versión sin gluten, sustituya por su pan sin gluten favorito. No olvide agregar el agua debajo de la canasta para evitar que salga humo. Si usa mantequilla o margarina con sal, puede omitir agregar más sal."],[]))
X.append(r(9588635,"Albóndigas de frijoles negros","Exterior crujiente con centros más suaves que se derriten en la boca y una textura fantástica. Estas albóndigas de frijoles negros son el aperitivo o plato principal perfecto.","17 albóndigas","1 porción",
["1 lata de 15 onzas de frijoles negros (escurridos + enjuagados (aprox. 1.5 tazas cocidos))","1 taza de avena en hojuelas","2 cucharadas de salsa de soya baja en sodio (o tamari para versión sin gluten)","2 cucharadas de agua","2 cucharadas de levadura nutricional","2 cucharaditas de ajo en polvo","2 cucharaditas de cebolla en polvo","2 cucharaditas de pimentón ahumado","sal + pimienta (al gusto)"],
["Precaliente el horno a 375℉/190℃ y forre una bandeja para hornear con papel pergamino.","Agregue todos los ingredientes al procesador de alimentos y procese hasta que se combinen, PERO NO PROCESE DE MÁS. Mantenga la textura con trozos; no queremos un puré.","Tome porciones de aprox. 1 cucharada de la mezcla y forme bolitas. Debería obtener 17-18 bolitas. Colóquelas en la bandeja para hornear.","Hornee durante 8 minutos, luego voltee las bolitas y hornee otros 8-10 minutos hasta que estén crujientes y firmes al tacto. No hornee de más.","Sirva tal cual, O con pasta y salsa marinara, O con salsa barbacoa y arroz."],[],[]))
X.append(r(9590770,"Chocolate caliente bajo en calorías [solo 80 calorías]","¡Una opción saludable de chocolate caliente, baja en calorías y deliciosa!","1 porción","1 porción",
["1.5 tazas de leche de almendras sin azúcar o la leche vegetal de su elección","1 cucharada de cacao crudo sin azúcar","1-2 cucharaditas de jarabe de arce","¼ de cucharadita de extracto puro de vainilla, opcional","pizca de sal marina, opcional"],
["Bata todos los ingredientes en una olla pequeña y caliente a fuego medio-alto hasta alcanzar la temperatura deseada.","Disfrute de inmediato."],
["La información nutricional refleja una cucharadita de jarabe de arce. Para una versión sin azúcar, simplemente omita el jarabe de arce. Para una versión sin nueces, use leche de soya o leche de avena en lugar de almendras. Pero elija variedades sin azúcar para evitar azúcar añadida. Para una versión más rica (por supuesto, no tan baja en calorías) use leche de coco enlatada. Prepárelo como chocolate caliente de menta agregando ⅛ de cucharadita de extracto de menta."],[]))
X.append(r(9591321,"Ensalada de betabel y camote","Una ensalada de betabel (remolacha) y camote (batata) es un plato vibrante y nutritivo que combina el dulzor terroso de los betabeles asados con la rica cremosidad de los camotes.","6 porciones","1 porción",
["3 tazas de betabel (remolacha) en cubos, aprox. 1 libra (cortado en cubos de media pulgada)","3 tazas de camote (batata) en cubos, aprox. 1 libra (cortado en cubos de media pulgada)","½ taza de arroz basmati enjuagado","1 taza de caldo de verduras","6 tazas de espinacas baby, aprox. 1 paquete de 5 onzas","1.5 tazas de frijoles cannellini blancos, aprox. 1 lata de 15 onzas, escurridos + enjuagados","½ taza de mitades de nuez pecana","¼ de taza de arándanos rojos secos o granada",("Para el aderezo","¼ de taza de tahini"),("Para el aderezo","3 cucharadas de vinagre de manzana"),("Para el aderezo","2 cucharadas de jarabe de arce"),("Para el aderezo","1 cucharadita de ajo en polvo"),("Para el aderezo","1 cucharadita de jengibre en polvo"),("Para el aderezo","sal + pimienta al gusto")],
["Precaliente el horno a 425℉/218℃ en modo de asado con convección y forre una bandeja para hornear con papel pergamino.","Distribuya los cubos de betabel y camote pelados en una sola capa sobre la bandeja y espolvoree generosamente con sal y pimienta negra. Áselos de 20 a 25 minutos, o hasta que los bordes estén dorados y los cubos estén tiernos al pincharlos con un tenedor.","Mientras tanto, agregue el arroz y el caldo de verduras a una olla pequeña y lleve a ebullición. Luego reduzca el fuego y cocine a fuego lento hasta que esté cocido y se haya absorbido casi todo el líquido. Esponje con un tenedor y reserve para que se enfríe un poco.","Agregue todos los ingredientes del aderezo para ensalada a un tazón pequeño y bata para combinar. Reserve.","Cuando las verduras asadas y el arroz estén listos, agréguelos, junto con todos los demás ingredientes de la ensalada, a un tazón para mezclar. Luego vierta el aderezo para ensalada y mezcle bien hasta cubrir de manera uniforme. Pruebe la sal y la pimienta y ajuste si es necesario."],
["Corte los cubos de betabel y camote lo más uniformes posible para que se cocinen de manera pareja.","Para ahorrar tiempo de preparación, puede usar camotes y betabeles ya cortados en cubos.","Si no tiene un horno de convección, ase las verduras un poco más de tiempo, hasta que estén tiernas al pincharlas con un tenedor y los bordes estén dorados.","Guarde las sobras en el refrigerador en un recipiente hermético de 3 a 4 días."],[]))
X.append(r(9592646,"Calabaza espagueti en freidora de aire","¡Calabaza espagueti perfecta en freidora de aire, siempre! Es fácil, requiere pocos ingredientes y está lista en 25 minutos o menos.","2 porciones","1 porción",
["2 libras de calabaza espagueti (1 calabaza pequeña, pero pésela para obtener resultados más exactos)","2 cucharaditas de aceite de aguacate o el de su elección, *omita para una versión sin aceite, vea las notas","½ cucharadita de sal marina","¼ de cucharadita de pimienta negra, opcional","¼ de cucharadita de ajo en polvo, opcional","¼ de cucharadita de pimentón ahumado, opcional",("Decoraciones opcionales","queso parmesano vegano"),("Decoraciones opcionales","perejil fresco")],
["Corte una rebanada delgada de los extremos de la calabaza y luego córtela por la mitad, a lo largo, lo más uniformemente posible. Coloque las dos mitades en la canasta de la freidora de aire, con el lado cortado hacia arriba. Luego rocíe con el aceite (si lo usa) y espolvoree de manera uniforme con los condimentos.","Cocine a 360 grados F durante 20 minutos, o hasta que un tenedor atraviese fácilmente la pulpa. (Esto puede variar según el tamaño de su calabaza.)","Una vez cocida, pásela a un plato y esponje el interior con un tenedor. Luego agregue el queso parmesano y el perejil fresco, si los usa, y disfrute."],
["Corte la calabaza por la mitad lo más equitativamente posible para que se cocine de manera uniforme. Diferentes freidoras de aire pueden cocinar a distintas velocidades. Yo uso una Ninja Foodi, pero si tiene otro modelo, empiece a revisar la calabaza alrededor de los 15 minutos y cocine hasta que esté tierna al pincharla con un tenedor. El tamaño de su calabaza espagueti determinará el tiempo de cocción. Yo cociné una calabaza de 2 libras en mi Ninja Foodi durante 20 minutos con resultados perfectos. Si su calabaza es más pequeña o más grande, ajuste el tiempo de cocción. *Para una versión sin aceite, omita el aceite y rocíe o vierta un poco de caldo de verduras por encima para dar humedad antes de cocinar. Yo uso una Ninja Foodi de 8 cuartos, pero cualquier modelo en el que quepa su calabaza debería funcionar bien. Si no tiene una freidora de aire, igualmente puede prepararla en el horno. Precaliente a 400 grados F, corte la calabaza por la mitad y sazone según las indicaciones. Luego hornee en una bandeja forrada con papel pergamino de 35 a 45 minutos, hasta que esté tierna al pincharla con un tenedor. Las sobras se conservan refrigeradas en un recipiente hermético durante 3 días o congeladas hasta por 3 meses."],[]))
X.append(r(9596194,"Pan vegano de manzana [sin aceite]","Este pan vegano de manzana es increíblemente húmedo y fácil de preparar en un solo tazón. Es deliciosamente dulce, con un hermoso remolino de canela.","12 rebanadas (1 pan de 5\"x9\")","1 porción",
["270 gramos de harina integral de trigo, aprox. 2 ¼ tazas (use el peso para mayor exactitud)","½ taza de azúcar de coco sin refinar","3 cucharaditas de polvo para hornear","1 cucharadita de canela","½ cucharadita de nuez moscada","¼ de cucharadita de sal marina","1.5 tazas de manzanas picadas en cubos (píquelas muy pequeñas)","½ taza de puré de manzana sin azúcar","1 taza de leche de soya",("Remolino dulce de canela opcional","2 cucharadas de azúcar de coco sin refinar"),("Remolino dulce de canela opcional","1 cucharadita de canela")],
["Precaliente el horno a 350℉/176℃ y forre un molde para pan con papel pergamino.","Agregue todos los ingredientes secos a un tazón grande y bata. Luego agregue el puré de manzana y la leche de soya y revuelva hasta que no queden partes secas, sin mezclar de más. Luego incorpore con movimientos envolventes las manzanas picadas, reservando un puñado pequeño para espolvorear encima.","OPCIONAL: Si usa el remolino de canela, mezcle el azúcar y la canela en un tazón pequeño. Luego vierta la mitad de la masa del pan de manzana en el molde y espolvoree la mezcla dulce de canela encima en una capa uniforme. (Si lo desea, puede reservar una pequeña cantidad de la mezcla para espolvorear sobre la segunda mitad de la masa.) Luego vierta la otra mitad de la masa encima del remolino, haciendo su mejor esfuerzo por extenderla de manera uniforme, sin mezclar el remolino con la masa. Si reservó algunos trozos de manzana, espolvoréelos encima, presiónelos suavemente y espolvoree encima de las manzanas cualquier mezcla restante de azúcar y canela.","Si omite el remolino de canela, vierta toda la masa en el molde preparado y espolvoree encima los trozos de manzana reservados.","Hornee de 45 a 55 minutos, o hasta que un palillo insertado en el centro del pan salga casi limpio, o con unas pocas migas. Luego retírelo del horno y déjelo enfriar durante 10 minutos sobre una rejilla antes de pasar el pan a una tabla de cortar. Continúe enfriando otros 5-10 minutos si puede esperar (facilita el corte). Luego corte el pan en rebanadas y disfrute."],
["Pese la harina para obtener los mejores resultados. Si no tiene una báscula de cocina, ponga la harina con una cuchara en la taza medidora y nivele con un cuchillo plano. Nunca tome la harina con la taza directamente de la bolsa.","Como la mayoría de los productos horneados, no mezcle demasiado la masa. Al agregar los ingredientes húmedos a los secos, revuelva hasta que no queden partes con harina e incorpore suavemente los trozos de manzana.","Pique las manzanas muy pequeñas. Los trozos pequeños se distribuyen de manera más uniforme.","Prepare y corte las manzanas DESPUÉS de preparar el resto de los ingredientes para que no se oscurezcan. O rocíelas con jugo de limón si está trabajando con anticipación.","Este pan es muy húmedo y cada horno varía. Hornee el pan vegano de manzana hasta que un palillo insertado en el centro salga casi seco. Eso puede tomar un poco menos o un poco más de tiempo, según su horno. Empiece a revisar el punto de cocción alrededor de los 45 minutos.","Las sobras se conservan cubiertas a temperatura ambiente durante 2 días, refrigeradas hasta por 5 días, o en el congelador hasta por 3 meses. Asegúrese de que el pan esté completamente frío antes de congelarlo."],[]))
X.append(r(9596706,"Galletas veganas de jengibre fáciles [sin aceite]","Las galletas veganas de jengibre son crujientes por fuera, suaves y masticables por dentro. ¡Llenas de especias navideñas, preparadas en un solo tazón y listas en solo 20 minutos!","10 galletas","1 galleta",
["200 gramos de harina de avena, aprox. 2 tazas escasas","2 cucharaditas de jengibre molido","1 cucharadita de canela","¼ de cucharadita de clavo molido","1 cucharadita de bicarbonato de sodio","⅓ de taza de melaza de primera calidad (fancy)","⅓ de taza de puré de manzana sin azúcar","1-2 cucharadas de leche vegetal, solo si es necesario",("Cobertura opcional","2-3 cucharadas de azúcar blanca para rodar las galletas")],
["Precaliente el horno a 350 grados F y forre una bandeja para hornear con papel pergamino.","Agregue todos los ingredientes secos a un tazón grande y bata bien. Luego agregue la melaza y el puré de manzana y mezcle hasta que no queden partes con harina. Agregue 1-2 cucharadas de leche vegetal SOLO si es necesario. (Si pesa la harina, no la necesitará.)","Divida la masa en 10 porciones y forme con cada una bolitas de aprox. 1-1.5\" de diámetro. Luego páselas por el azúcar (si la usa), aplánelas ligeramente y colóquelas en la bandeja para hornear.","Hornee durante 10 minutos, luego retire del horno y deje enfriar por lo menos 5 minutos hasta que se firmen. ¡Disfrute!"],
["Pese la harina para obtener los resultados más exactos. Si no tiene una báscula de cocina, use dos tazas escasas de harina de avena. Si usa una báscula y no hace ninguna sustitución, no debería necesitar nada de la leche vegetal. Si toma la harina con la taza directamente de la bolsa (no recomendado), puede terminar con más harina de la necesaria. Así que si la masa de las galletas se ve demasiado seca después de mezclar (debe estar pegajosa y húmeda, consulte las fotos de arriba), agregue 1-2 cucharadas de leche, según sea necesario. Hornee durante 10 minutos, y no más. Estas galletas veganas de jengibre pueden parecer poco cocidas a los 10 minutos, pero se firmarán bastante rápido una vez fuera del horno. Use una cuchara para galletas para obtener galletas de jengibre del mismo tamaño. O divida la masa en 10 porciones iguales antes de formar las galletas. Para una galleta un poco más crujiente, presiónelas antes de hornear. Para una galleta de jengibre más esponjosa y masticable, solo forme las bolitas y hornee. No se extenderán mucho, pero se cocinarán por completo en los 10 minutos de horneado. Use las manos húmedas para formar las galletas y evitar que la masa se pegue a las manos. Las sobras se conservan cubiertas o en un recipiente sellado a temperatura ambiente de 2 a 3 días. Sin embargo, si vive en un clima caluroso/húmedo, el azúcar con que se rodaron puede derretirse a temperatura ambiente. O puede congelarlas en un recipiente hermético hasta por 2 meses."],[]))
X.append(r(9602754,"Magdalenas saludables de betabel","Estas magdalenas saludables de betabel (remolacha) son un bocadillo vibrante y nutritivo, ¡perfecto para el desayuno o el postre!","12 magdalenas","1 porción",
[("Ingredientes húmedos","2 latas de 398 ml (2 x 14 onzas) de betabeles (remolachas) enlatados, escurridos (aprox. 2.5 tazas de betabel en cubos)"),("Ingredientes húmedos","¼ de taza de puré de manzana sin azúcar"),("Ingredientes húmedos","3 cucharadas de jarabe de arce"),("Ingredientes húmedos","1 cucharadita de vinagre de manzana"),("Ingredientes secos","300 gramos de harina de almendra blanqueada superfina, aprox. 3 tazas escasas"),("Ingredientes secos","2 cucharaditas de polvo para hornear"),("Ingredientes secos","½ cucharadita de bicarbonato de sodio"),("Opcional","⅓ de taza de chispas de chocolate veganas, más algunas más para decorar las magdalenas si lo desea")],
["Precaliente el horno a 350℉/176℃ y forre un molde para magdalenas con capacillos de papel pergamino.","Agregue todos los ingredientes húmedos a una licuadora y procese hasta que quede completamente suave. Reserve.","Luego bata los ingredientes secos en un tazón grande. Vierta los ingredientes líquidos hechos puré en el mismo tazón de la harina y revuelva hasta combinar.","Incorpore las chispas de chocolate si las usa, y luego divida la masa entre los 12 moldes para magdalenas, llenándolos casi hasta arriba.","Hornee las magdalenas de 28 a 30 minutos, o hasta que un palillo insertado en el centro de una magdalena salga limpio y seco.","Retire el molde del horno y deje reposar las magdalenas a temperatura ambiente por lo menos 20-30 minutos antes de pasarlas a una rejilla para que terminen de firmarse."],
["Pese la harina para obtener los resultados más exactos. Si no tiene una báscula de cocina, ponga la harina con una cuchara en la taza medidora y use un cuchillo para nivelar el exceso, con resultados similares. ¡No la tome con la taza directamente de la bolsa!","Si usa betabeles enlatados, asegúrese de que no estén en escabeche. Use betabeles enlatados solo en agua, sin vinagre ni aceite, ya que eso alteraría el sabor.","Use polvo para hornear fresco y activo. El polvo para hornear que lleva abierto en su despensa más de 6 meses puede perder su efectividad.","Golpee suavemente el molde de magdalenas sobre una superficie dura para cerrar los espacios en la masa antes de hornear.","Deje enfriar las magdalenas en el molde por lo menos 20-30 minutos antes de manipularlas. Son delicadas y necesitan tiempo para firmarse por completo antes de pasarlas a una rejilla.","Las sobras se conservan a temperatura ambiente hasta por 2 días, en el refrigerador hasta por 5 días, o congeladas hasta por 3 meses."],[]))
X.append(r(9602755,"Pudín de chía y fresa","El pudín de chía y fresa es un postre cremoso y nutritivo que se prepara combinando fresas frescas, semillas de chía y leche vegetal.","2 porciones","1 porción",
["1 taza de fresas frescas","1 taza de leche de nuez de la India (anacardo) sin azúcar (o la leche no láctea de su elección)","4 cucharadas de semillas de chía","1 cucharada de jarabe de arce (opcional, para más dulzor)"],
["Licúe las fresas y la leche en una licuadora pequeña para hacer leche de fresa.","Una vez que esté suave, pase la leche de fresa a un frasco o recipiente de vidrio y agregue las semillas de chía. Revuelva bien y refrigere durante 6 horas, o toda la noche.","Disfrute con más fresas frescas encima, otras frutas, nueces, granola, avena y/o coco rallado."],[],[]))
X.append(r(9602951,"Sustituto de huevo con chía (¡o con linaza también!)","Un sustituto de huevo con chía (o huevo de linaza) es sencillo y versátil. ¡Aprenda a usar este sustituto en todas sus recetas favoritas de productos horneados!","1","1 huevo",
["1 cucharada de semillas de chía o de linaza molida","3 cucharadas de agua"],
["En un tazón pequeño, combine la chía o la linaza con el agua. Deje reposar durante 5 minutos (o más) y use en sus recetas favoritas."],
["No necesita moler las semillas para preparar este huevo de chía. Sin embargo, si desea ocultar la textura de las semillas a los comensales más exigentes, adelante. O, si no quiere verlas en el producto terminado, use semillas blancas en lugar de negras. Aunque puede usar huevo de linaza y huevo de chía de manera intercambiable en la mayoría de las recetas de productos horneados, yo prefiero la chía por su sabor neutro. Dicho esto, uso lo que tenga disponible en la despensa, ¡así que use lo que tenga!"],[]))
X.append(r(9604269,"Salsa vegana de queso de nuez de Castilla [sin aceite]","¡La salsa vegana de queso de nuez de Castilla está llena de sabor, requiere solo 5 ingredientes y se prepara en solo cinco minutos! No requiere cocinar ni picar.","6 porciones","1 porción",
["1 ¼ tazas de nueces de Castilla","2 cucharadas de levadura nutricional","½ cucharadita de cebolla en polvo","½ cucharadita de sal marina","¾ de taza de agua caliente, más una o dos cucharadas adicionales opcionales para lograr la consistencia deseada"],
["Con una tetera o una olla pequeña, hierva una o dos tazas de agua fresca. (Ya que una parte se evaporará.)","Agregue todos los ingredientes, usando solo 3/4 de taza del agua caliente, a su licuadora y procese hasta que quede suave y cremoso. Tomará aproximadamente un minuto para que las nueces se descompongan por completo y queden suaves. Si es necesario, apague la licuadora y vuelva a encenderla hasta lograr la textura deseada. Pruebe el sazón y ajuste si es necesario. Si prefiere una salsa más líquida, agregue 1-2 cucharadas adicionales de agua y licúe de nuevo."],
["No es necesario remojar las nueces de Castilla si tiene una licuadora potente. Si no, remójelas durante 30 minutos en agua caliente y luego escúrralas antes de agregarlas a la licuadora. Si no usa una licuadora potente, apáguela, espere 30 segundos y vuelva a encenderla hasta que el queso de nuez de Castilla quede suave. (Esto ayudará a evitar el sobrecalentamiento en una licuadora menos potente.) Agregue 1-2 cucharadas de agua caliente adicional, según sea necesario para lograr la consistencia deseada, si prefiere una salsa más líquida. ¡Cámbiela! Si desea variar los sabores, sustituya la cebolla en polvo por ajo en polvo, pimentón, pimentón ahumado o cualquier otra especia que desee. (Tenga en cuenta que los condimentos más oscuros cambiarán el color de su salsa de queso de nuez de Castilla.) Las sobras se conservan en un recipiente sellado en el refrigerador durante 3 días. Recaliente antes de servir."],[]))
X.append(r(9605778,"Masa de tarta integral sin aceite","¡Una sencilla masa de tarta sin aceite, vegana, sin nueces y hecha con una mezcla de harina blanca e integral para un postre más saludable! Es fácil de preparar y perfecta para tartas dulces y saladas.","8 porciones","1 porción",
["90 gramos (aprox. ¾ de taza) de harina de trigo todo uso sin blanquear O 90 gramos de harina de almendra","80 gramos (aprox. ¾ de taza) de harina integral blanca de trigo, también conocida como harina integral suave o harina integral para repostería","1 aguacate mediano maduro, pelado y sin hueso","¼ de cucharadita de sal marina (aumente a ½-3/4 de cucharadita para tartas saladas)","4 cucharadas de leche de coco sin azúcar Thai Kitchen, ¡agite muy bien antes de abrir la lata! (Si usa la opción de harina de almendra, puede usar cualquier leche no láctea.)","1-2 cucharadas de agua, ¡SOLO si es necesario!",("Opcional","2 cucharadas de azúcar de coco o azúcar granulada de su elección (omita para tartas saladas)"),("Opcional","1 cucharadita de canela (omita para tartas saladas)")],
[("Instrucciones de preparación","Engrase ligeramente un molde para tarta de 9 pulgadas o corte un círculo de papel pergamino para colocarlo dentro. Reserve."),("Instrucciones de preparación","Agregue todos los ingredientes EXCEPTO el agua al procesador de alimentos y procese hasta que se combinen, sin mezclar de más."),("Instrucciones de preparación","Enharine ligeramente una hoja de papel pergamino sobre la encimera y reúna con las manos la mezcla del procesador para formar una bola. Si la mezcla está muy seca o se desmorona, agregue una cucharada de agua a la masa y mezcle muy bien con las manos. (No debería necesitar el agua si pesa la harina con una báscula de cocina.) Lo que busca es una bola de masa con una consistencia parecida a la plastilina. Ni muy seca, ni tan húmeda como para quedar pegajosa."),("Instrucciones de preparación","Coloque la masa sobre el papel pergamino enharinado y espolvoree un poco de harina sobre la bola de masa y sobre el rodillo. Luego use el rodillo para extender la masa en un círculo de aproximadamente 10-11 pulgadas de ancho. (Un poco más ancho que su molde.) La masa debe tener aproximadamente 1/4 de pulgada de grosor; haga su mejor esfuerzo por extenderla lo más uniformemente posible."),("Instrucciones de preparación","Ahora, use el papel pergamino para voltear la masa sobre el molde para tarta. Luego retire con cuidado el papel pergamino. Use las manos para presionar la masa en el molde, por el fondo y los bordes. Si tiene alguna rotura, use los dedos húmedos para presionar y volver a unir la masa."),("Instrucciones de preparación","Luego recorra los bordes y use un cuchillo para recortar el exceso de masa."),("Instrucciones de preparación","Opcional: Use los dedos para hacer un diseño decorativo alrededor de los bordes, si lo desea. (Vea las fotos del proceso arriba.) ¡No tiene que ser perfecto!"),("Instrucciones de preparación","Pinche el fondo de la masa de tarta con un tenedor, por todas partes, para permitir que escape el vapor, y luego hornee."),("Instrucciones de horneado","Si va a preparar una tarta con relleno sin hornear: Precaliente el horno a 350 grados F y hornee la masa en blanco durante 15-20 minutos, hasta que los bordes estén dorados, y luego retire del horno. Deje enfriar por completo antes de rellenar para una tarta que no requiere más horneado. Por ejemplo, mi tarta de limón, de limón verde (key lime) o de fresa."),("Instrucciones de horneado","Si va a preparar una tarta con un tiempo de cocción largo: Precaliente el horno a 350 grados F (por ejemplo, una tarta de arándanos o de manzana) y hornee la masa en blanco durante 10-15 minutos. Luego retire del horno y rellene (no es necesario dejar enfriar primero) y continúe horneando el tiempo recomendado para esa receta. (Generalmente entre 40 y 60 minutos.) O para una tarta con un tiempo de cocción largo que no requiere hornear la masa en blanco, simplemente rellénela cruda y hornee según las instrucciones de su tarta. Por ejemplo, mi tarta de nuez pecana no requiere hornear la masa en blanco.")],
["***Vea la masa de tarta en acción en el video de arriba de nuestra tarta vegana de limón*** Para obtener los mejores resultados, use una báscula de cocina y pese la harina. Guiarse por medidas no es tan exacto como el peso. Trate de no procesar demasiado la mezcla en el procesador de alimentos. Pulse hasta que se combine y luego pásela a una superficie limpia para continuar a mano. Asegúrese de enharinar ligeramente su superficie de trabajo y el rodillo, para evitar que se pegue. Al extender la masa, ayuda levantarla y moverla entre cada pasada del rodillo, para que no se pegue demasiado. No agregue agua, a menos que sea necesario. Si usa una báscula de cocina, no debería necesitar nada de agua. Si está trabajando con anticipación, puede preparar la masa en forma de bola, envolverla bien y refrigerarla. Luego retírela del refrigerador unos 20 minutos antes de extenderla. Si va a preparar una tarta con un tiempo de horneado largo (como de manzana o de arándanos), cubra los bordes de la tarta con un aro de papel de aluminio (corte un aro de papel de aluminio) o con un protector de tarta, si tiene uno, para evitar que los bordes se quemen."],[]))
X.append(r(9605903,"Salsa Alfredo vegana fácil","¡Una irresistible salsa Alfredo vegana que usa ingredientes sencillos y se prepara en 5 minutos!","6 porciones","1 porción",
["1 taza de nueces de la India (anacardos) crudas","2 cucharadas de jugo de limón, aprox. la mitad de un limón grande","¾ de taza de agua caliente","¼ de cucharadita de ajo en polvo","¼ de cucharadita de cebolla en polvo","⅛ de cucharadita de tomillo seco","½ cucharadita de sal marina","¼ de cucharadita de pimienta negra",("Decoración opcional","queso parmesano vegano")],
["Agregue todos los ingredientes a una licuadora potente y procese a velocidad alta hasta que quede suave y cremoso. Continúe procesando para asegurarse de que no queden trocitos de nuez de la India. Agregue 2-3 cucharadas de queso parmesano vegano si lo desea.","Sirva con sus fideos o verduras favoritos."],
["Use agua caliente para no tener que calentar la salsa en una sartén después.","Si no tiene una licuadora potente, remoje las nueces de la India en agua hirviendo de 20 a 30 minutos para ablandarlas. Luego escúrralas y licúelas con los demás ingredientes.","Si no puede consumir nueces de la India ni otras nueces, use semillas de girasol con resultados similares.","La salsa sobrante se conserva refrigerada de 4 a 5 días, o congélela en recipientes aptos para congelador hasta por 3 meses."],[]))
save(3,X)
